import{_ as t}from"./chunks/eye.BRl0ZGNz.js";import{_ as a,c as o,o as r,ag as s}from"./chunks/framework.DZ_cNctr.js";const l="/docs/screenshots/labels-overview.png",n="/docs/screenshots/labels-toolbar.png",i="/docs/screenshots/labels-row-expanded.png",d="/docs/screenshots/labels-style-popover.png",h="/docs/screenshots/labels-group-by-menu.png",c="/docs/screenshots/labels-search.png",p="/docs/screenshots/labels-metadata.png",x=JSON.parse('{"title":"Labels","description":"Load and display segmentation masks on OME-Zarr images. Add embedded labels, local folders, or remote URLs. Control opacity, fill/contour rendering, coloring, grouping, tags, notes, and key-value metadata.","frontmatter":{"title":"Labels","description":"Load and display segmentation masks on OME-Zarr images. Add embedded labels, local folders, or remote URLs. Control opacity, fill/contour rendering, coloring, grouping, tags, notes, and key-value metadata."},"headers":[],"relativePath":"guides/labels.md","filePath":"guides/labels.md"}'),g={name:"guides/labels.md"};function u(b,e,m,y,f,w){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h1><p>A <strong>label</strong> is a segmentation mask: one integer per pixel, where each integer is an object ID. Labels live alongside your image and render as a coloured overlay so you can see what was detected by your segmentation tool (CellProfiler, Cellpose, StarDist, InstanSeg, and anything else that writes OME-Zarr or bare Zarr masks).</p><p>This guide covers the foundational workflow: load labels, control how they look, organise them, attach metadata. For per-object coloring by measurement CSVs (heatmap, category, phenotypes), see the <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping guide</a>.</p><p><img src="'+l+'" alt="The Labels tab open with several embedded labels and one external label marked EXT, and a coloured segmentation overlay on the image" style="max-width:100%;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="loading-labels" tabindex="-1">Loading labels <a class="header-anchor" href="#loading-labels" aria-label="Permalink to &quot;Loading labels&quot;">​</a></h2><p><img src="'+n+'" alt="Top of the Labels tab on a plate, showing the Discover, Add Local, Add URL and Refresh buttons, with the list still empty because nothing has been scanned yet" style="max-width:420px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>The buttons at the top of the <strong>Labels tab</strong>:</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Add Local</strong></td><td>Pick a folder on your disk that contains a Zarr label array. Chrome / Edge only.</td></tr><tr><td><strong>Add URL</strong></td><td>Paste a URL pointing at a Zarr label array. Works in any browser.</td></tr><tr><td><strong>Discover</strong></td><td>Scan an HCS plate&#39;s fields for labels. Only appears on plates, and only runs when you click it. See below.</td></tr><tr><td><strong>Refresh</strong></td><td>Re-scan the current image&#39;s OME-Zarr for embedded labels. Useful if a segmentation job has just written a new label and you don&#39;t want to reload the whole image.</td></tr></tbody></table><h3 id="embedded-labels" tabindex="-1">Embedded labels <a class="header-anchor" href="#embedded-labels" aria-label="Permalink to &quot;Embedded labels&quot;">​</a></h3><p>Labels written inside your OME-Zarr (under the <code>/labels/</code> group, per the OME-NGFF spec) are discovered automatically on image load. No clicking required. They appear in the <strong>Embedded</strong> group in the list.</p><h3 id="plates-press-discover" tabindex="-1">Plates: press Discover <a class="header-anchor" href="#plates-press-discover" aria-label="Permalink to &quot;Plates: press Discover&quot;">​</a></h3><p>On an HCS plate, labels are <strong>not</strong> discovered automatically. You get a <strong>Discover</strong> button instead, and nothing is scanned until you press it.</p><p>This is deliberate. The scan asks <strong>every well</strong> whether it has a <code>labels/</code> group, so a 384-well plate is 384 requests before a single pixel is drawn. Ten run in parallel, and only field 0 of each well is checked, but the count still scales with the plate. Against a local disk that is merely slow. Against S3 it is 384 billed requests every time anyone opens the plate, whether or not they wanted labels at all. So the scan is something you ask for, not something that happens to you.</p><p>Because it visits every well, the result knows which wells actually carry each label, rather than assuming the whole plate matches the first one.</p><p>Press Discover once and the labels stay attached for the session. If a segmentation job writes new masks while you have the plate open, press it again.</p><h3 id="local-folders-add-local" tabindex="-1">Local folders (Add Local) <a class="header-anchor" href="#local-folders-add-local" aria-label="Permalink to &quot;Local folders (Add Local)&quot;">​</a></h3><p>Click <strong>Add Local</strong>, pick any folder containing a Zarr label. The folder stays on your disk. The viewer reads it directly via the File System Access API. Use this when you&#39;ve run a segmentation tool that wrote a Zarr mask next to (but not inside) your image.</p><h3 id="remote-urls-add-url" tabindex="-1">Remote URLs (Add URL) <a class="header-anchor" href="#remote-urls-add-url" aria-label="Permalink to &quot;Remote URLs (Add URL)&quot;">​</a></h3><p>Click <strong>Add URL</strong> and paste the URL of a Zarr label array. Works from any storage that serves HTTP range requests and the right CORS headers: S3, Cloudflare R2, GCS, Azure Blob, an on-premise nginx, a data server running locally. See the <a href="./data-server.html">Data Server guide</a> for hosting your own.</p><p>External labels (not embedded in the image&#39;s OME-Zarr) show an <strong>EXT</strong> badge in the list so you can tell them apart from the embedded ones.</p><div class="tip custom-block"><p class="custom-block-title">Try it on a public dataset</p><p><a href="https://find-nuclei.github.io/?url=https://uk1s3.embassy.ebi.ac.uk/idr/zarr/v0.4/idr0062A/6001240.zarr&amp;tab=labels&amp;l=src0_0" target="_blank" rel="noreferrer">Open IDR image 6001240 with its segmentation showing</a>. Nothing is downloaded to a server, and nothing is installed. The viewer reads the OME-Zarr straight from the Image Data Resource&#39;s public bucket, which serves range requests and CORS. Credit and licence for that image are <a href="#sample-images-used-in-this-guide">at the bottom of this page</a>.</p></div><h2 id="label-rows" tabindex="-1">Label rows <a class="header-anchor" href="#label-rows" aria-label="Permalink to &quot;Label rows&quot;">​</a></h2><p>Every label renders as a row with the essentials on a single line:</p><ul><li><img src="'+t+'" class="fn-icon" alt="visibility"> toggle visibility</li><li>Color swatch: click to open the style popover</li><li>Label name: double-click to rename</li><li>Filter count badge: appears when analytics is loaded, showing how many filters are active</li><li><strong>EXT</strong> badge: only on external labels</li></ul><p>Click the row to expand its detail panel below. There you&#39;ll find Metadata (Source / Notes / Tags / Key-values), plus the Analytics section if analytics is loaded.</p><p><img src="'+i+'" alt="A label row expanded, showing the Metadata section (Source, Notes textarea, Tags chips, Key-values mini-table)" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="style-solid-random-or-per-object" tabindex="-1">Style: solid, random, or per-object <a class="header-anchor" href="#style-solid-random-or-per-object" aria-label="Permalink to &quot;Style: solid, random, or per-object&quot;">​</a></h2><p>Click the color swatch on a label row to open the <strong>style popover</strong>. It holds the display controls for that label:</p><p><img src="'+d+'" alt="The style popover open showing the Solid / Random tabs (Heatmap / Category are grayed out when no CSV is loaded), Opacity slider, Render (FILL / CONTOUR) toggles, Presets color grid" style="max-width:320px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><table tabindex="0"><thead><tr><th>Control</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Solid</strong></td><td>Every object in the label shares a single colour (the one you pick below). Default for newly loaded labels.</td></tr><tr><td><strong>Random</strong></td><td>Each object gets a colour hashed from its ID. Different objects look different; the same object gets the same colour across reloads. Useful for visually distinguishing neighbouring cells without a segmentation-quality judgement.</td></tr><tr><td><strong>Heatmap</strong></td><td>Colour by a numeric column. Requires an analytics CSV. See the <a href="./analytics-phenotyping.html">Analytics guide</a>.</td></tr><tr><td><strong>Category</strong></td><td>Colour by a string column. Requires an analytics CSV.</td></tr><tr><td><strong>Opacity slider</strong></td><td>Blends the label layer with the image underneath. 0 hides the label; 1 makes it fully opaque.</td></tr><tr><td><strong>FILL / CONTOUR</strong></td><td>Two independent toggles for polygon labels. Fill paints the interior; contour draws a 1-px outline. Turn fill off for &quot;outlines-only&quot; view. Useful when you want to see the image through your segmentation.</td></tr><tr><td><strong>Presets grid</strong></td><td>16 curated colours: RGB primaries on top, muted variants on the bottom row. One click applies.</td></tr><tr><td><strong>Hex / RGB inputs</strong></td><td>Type <code>#FF00AA</code> or type the three RGB values directly. Synced bidirectionally.</td></tr><tr><td><strong>More colors…</strong></td><td>Opens the OS-native picker for any colour + eyedropper (Chrome / Edge).</td></tr></tbody></table><h2 id="grouping" tabindex="-1">Grouping <a class="header-anchor" href="#grouping" aria-label="Permalink to &quot;Grouping&quot;">​</a></h2><p>The Labels list groups by <strong>Source</strong> by default. Embedded labels sit under &quot;Embedded&quot;, and each external label gets its own group header. You can switch to <strong>Group By key-value</strong> using the toolbar:</p><p><img src="'+h+'" alt="The Group By control reading Group by: segmenter, with its menu open listing Clear grouping and the available keys, compartment and segmenter" style="max-width:260px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>A key-value describes the <strong>whole mask</strong>, not the objects inside it, so useful keys are properties of the segmentation run: <code>segmenter: stardist</code>, <code>model: nuclei_v2</code>, <code>version: 2026-03-11</code>. Tag a dozen masks with <code>segmenter</code> and the list reorganises into a StarDist group and a Cellpose group, which is what you want when you are comparing runs on the same image.</p><p>Things that vary <em>per object</em>, like a cell&#39;s tissue class, do not belong here. Those live in an analytics table, one row per object. See <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a>.</p><p>Drag the grip handle on the left of each group header to <strong>reorder groups</strong>. The group order also controls rendering z-order on the canvas. Later groups draw on top.</p><h2 id="search-and-filter" tabindex="-1">Search and filter <a class="header-anchor" href="#search-and-filter" aria-label="Permalink to &quot;Search and filter&quot;">​</a></h2><p>The toolbar row has a <strong>Filter</strong> dropdown and a <strong>Search</strong> input:</p><ul><li><strong>Filter</strong>: show All / only Visible / only Hidden labels.</li><li><strong>Search</strong>: type part of a label name, tag, or metadata value. The list narrows to matches live.</li></ul><p><img src="'+c+'" alt="Search input active, list narrowed to labels whose name contains &#39;nuclei&#39;" style="max-width:420px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><h2 id="metadata-source-notes-tags-key-values" tabindex="-1">Metadata: Source, Notes, Tags, Key-values <a class="header-anchor" href="#metadata-source-notes-tags-key-values" aria-label="Permalink to &quot;Metadata: Source, Notes, Tags, Key-values&quot;">​</a></h2><p>Expand a label&#39;s row and open the <strong>METADATA</strong> section. Four fields live here:</p><ul><li><strong>Source</strong>: read-only, shows where the label came from (embedded path, local folder, URL).</li><li><strong>Notes</strong>: free-form text. &quot;Run 2 from Cellpose, threshold 0.65.&quot;</li><li><strong>Tags</strong>: short chips you can add / remove. &quot;validated&quot;, &quot;needs-review&quot;.</li><li><strong>Key-values</strong>: structured <code>key: value</code> rows describing the mask as a whole. <code>segmenter: cellpose</code>, <code>model: cyto3</code>, <code>version: 2026-03-11</code>. Add one, then switch to <strong>Group By</strong> on the toolbar and the list reorganises by that key.</li></ul><p><img src="'+p+'" alt="Expanded METADATA section showing the read-only Source path, a Notes field, Tags, and the Key-values editor" style="max-width:380px;border:1px solid var(--vp-c-divider);border-radius:8px;margin:1rem 0;"></p><p>Metadata persists to IndexedDB per-label and survives reloads.</p><h2 id="hcs-plates" tabindex="-1">HCS plates <a class="header-anchor" href="#hcs-plates" aria-label="Permalink to &quot;HCS plates&quot;">​</a></h2><p>When you open a high-content-screening plate, labels work the same way but apply at the plate level. A label named <code>nuclei</code> is discovered on every populated well and renders consistently across all fields. See the <a href="./hcs-plates.html">HCS Plates guide</a> for plate-specific controls (well navigation, field grid, plate overview).</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Everything you do in the Labels tab persists to your browser&#39;s IndexedDB, keyed by the image&#39;s URL or local folder handle:</p><ul><li>Visibility, colour mode, opacity, fill/contour state</li><li>Notes, tags, key-values</li><li>Which labels you&#39;ve added external / URL-based</li><li>Current group-by mode</li></ul><p>Reload the page, reopen the image. Your label configuration is still there. The URL query string captures viewport state (zoom, center, active channels) but <strong>not</strong> label configuration; that lives in the browser locally.</p><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>On phone viewports the Labels tab shows the row list and basic visibility toggles, but <strong>heatmap / category / phenotype coloring tabs are disabled</strong>. Per-object coloring needs an analytics CSV, and the File System Access API required to pick one doesn&#39;t exist on phones. Tablets show the full desktop UI.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>The screenshots on this page use a public whole-slide H&amp;E section, a high-content screen and a fluorescence image from IDR. See <a href="./../sample-data.html">Sample Data and Credits</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Want to colour cells by area, intensity, or any measurement? <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a>.</li><li>Drawing your own regions (not from a segmentation mask)? <a href="./annotations.html">Annotations</a>.</li><li>Sharing your view with a reviewer? <a href="./sharing.html">Sharing Views</a>.</li><li>Hosting your own label data? <a href="./data-server.html">Data Server</a>.</li></ul>',57)])])}const S=a(g,[["render",u]]);export{x as __pageData,S as default};
